function addBox(position, html) {
    var box = L.control({ position: position });
    box.onAdd = function () {
        var div = L.DomUtil.create('div', 'box');
        div.innerHTML = html;
        return div;
    };
    box.addTo(map);
}

addBox('topright', '<h2>University of Pretoria</h2>');

